import java.util.*;

public class Main {
    int dietPlanPerformance(int[] calories, int k, int lower, int upper) {
        int n = calories.length;
        int points = 0;
        for (int start = 0; start <= n - k; start++) {
            int windowSum = 0;
            for (int i = start; i < start + k; i++) {
                windowSum += calories[i];                                         // re-add every element of this window from scratch
            }
            if (windowSum < lower) points--;
            else if (windowSum > upper) points++;
        }
        return points;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.dietPlanPerformance(new int[]{1, 2, 3, 4, 5}, 1, 3, 3));
    }
}

