def diet_plan_performance(calories, k, lower, upper):
    window_sum = 0
    points = 0
    for i, cal in enumerate(calories):
        window_sum += cal                                                # grow the window from the right
        if i >= k:
            window_sum -= calories[i - k]                                  # shrink from the left once the window exceeds size k
        if i >= k - 1:                                                     # only score once the window has reached its full size
            if window_sum < lower:
                points -= 1
            elif window_sum > upper:
                points += 1
    return points


